CREATE OR REPLACE FUNCTION chk_k10() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c4 IS NOT NULL AND NEW.c6 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c4 IS NOT NULL AND c6 IS NOT NULL AND c4=NEW.c4 AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c6 IS NOT NULL AND c6=NEW.c6) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c6 IS NULL AND c4 IS NOT NULL AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c6 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k10 violated'; END IF;
